import re

from robot.api import logger

from ta_egate_cmd_parser.egate_output_parser_base import EgateDispCommandsOutputParser
from ta_egate_cmd_parser.egate_command_base import EgateCommandBase
from ta_egate_cmd_parser.utils.converters import create_dict

THROUGHPUT_REGEXP = re.compile(r'(\d+\.\d\s[KMG]bps)|(0)')


# Function used to parse throughput value retrieved from mbms_stats cmd. Value is processed only if matches regexp.
# Used as argument for "parse_column_value_with_custom_function" method form "EgateDispCommandsOutputParser" class

def parse_throughput(value):
    """
    Normalizes units.
    :param value:
    :return:
    """
    throughput = re.search(THROUGHPUT_REGEXP, value)
    if throughput:
        if len(throughput.group(0)) == 1:
            return {'value': throughput.group(0), 'unit': None}
        else:
            return {'value': throughput.group(0).split()[0], 'unit': throughput.group(0).split()[1]}
    else:
        return value


class MbmsStatsFailure(Exception):
    """
    Exception class for mbms_stats
    """
    pass


class MbmsStats(EgateCommandBase):
    """
    Parser for mbms_stats command output.
    """

    def __init__(self, **params):
        """

        :param params:
        """
        super(MbmsStats, self).__init__()
        self.command = 'mbms_stats'
        self.params = params
        self.executed_phrase = r'EGATE>\seNB\-.*?EGATE>\s*'
        self.fail_regexp = 'Error'
        self.to_execute = self.command
        self._build_command()
        logger.debug('{}: {} command to execute:\n{}'.format(self.__class__.__name__, self.command, self.to_execute))

    def execute_and_parse(self, egate_id=0):
        """
        Execute egate cmd and parse its output.
        :return: parsed output
        """
        status, output = self.execute(egate_id=egate_id, command=self.to_execute)
        if status:
            parsed_output = self._parse_mbms_stats_output(output)
            logger.debug('{}: {} cmd parsed output:\n{}'.format(self.__class__.__name__, self.command, parsed_output))
            return parsed_output
        else:
            raise MbmsStatsFailure(output)

    def _build_command(self):
        """
        Build mbms_stats command.
        :return: None
        """
        for param, value in list(self.params.items()):
            if param == 'display' or param == 'clear':
                self.to_execute += ' {}'.format(param)
            else:
                self.to_execute += ' {}={}'.format(param, value)

    def _parse_mbms_stats_output(self, cmd_output):
        """
        Parse mbms_stats command output.
        :param cmd_output: output received from execution of mbms_stats command
        e.g.:

        eNB-1 cell-13 lcid=27: MBMS Session Throughput (TMGI=1:244:09, MBSFN area=0)
        ============================================
        Last        Minimum  Maximum     Average
        --------------------------------------------
        428.9 Kbps  0        440.5 Kbps  413.8 Kbps
        ============================================

        EGATE>

        :return: dict containing values of avg, min, max and last throughput
        e.g.:
        {
        ...  'Average': [ { 'unit': 'Kbps', 'value': '413.8' } ],
        ...  'Minimum': [ { 'unit': None, 'value': '0' } ],
        ...  'Last': [ { 'unit': 'Kbps', 'value': '428.9' } ],
        ...  'Maximum': [ { 'unit': 'Kbps', 'value': '440.5' } ]
        }
        """
        if re.findall(r'Error:.*', str(cmd_output)):
            raise MbmsStatsFailure(re.findall(r'Error:.*', str(cmd_output))[0])
        else:
            cmd_parser = EgateDispCommandsOutputParser(cmd_output)
            cmd_parser.parse_column_value_with_custom_function('Last', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Average', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Minimum', parse_throughput)
            cmd_parser.parse_column_value_with_custom_function('Maximum', parse_throughput)
            output = cmd_parser.get_list_of_output_parsed_lines()

            return create_dict(list_of_output_parsed_lines=output)
